export const dir=path.dirname(fileURLToPath(import.meta.url));
export const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
export const assert=(c,m)=>{if(!c)throw new Error(m)};
export const load=f=>JSON.parse(fs.readFileSync(f,'utf8'));
const preFile=path.join(dir,'pre-import-inventory.json');
assert(sha(fs.readFileSync(preFile))==='523b7a63820ce8e25a07dcfe587711e3210bbd9a9895a00f0747fc29f0e76735','PREP artifact changed');
export const pre=load(preFile);
export function verify(gradedCount=0,summarizedCount=0){
 const batchFiles=new Set(pre.batches.map(b=>path.resolve(b.file)));let unchangedFiles=0;
 for(const r of pre.inventory){if(batchFiles.has(path.resolve(r.file)))continue;const b=fs.readFileSync(r.file);assert(b.length===r.bytes&&sha(b)===r.sha256,'immutable original/control/runtime drift '+r.file);unchangedFiles++;}
 const modifications=[];let originalFieldsRecovered=0;
 for(const br of pre.batches){const originalBytes=fs.readFileSync(br.snapshotFile);assert(originalBytes.length===br.originalBytes&&sha(originalBytes)===br.originalSha256,'original batch snapshot changed');const original=JSON.parse(originalBytes),actualBytes=fs.readFileSync(br.file),actual=JSON.parse(actualBytes),inverse=structuredClone(actual);
  const assigned=pre.records.slice(0,gradedCount).filter(r=>path.resolve(r.batchFile)===path.resolve(br.file));
  for(const r of assigned){const state=inverse.cases[r.variant],origState=original.cases[r.variant];const a=state.attempts.find(a=>a.attemptId===r.attemptId),oa=origState.attempts.find(a=>a.attemptId===r.attemptId);assert(a&&oa,'exact imported attempt missing');assert(Array.isArray(a.reviews)&&a.reviews.length===(oa.reviews?.length??0)+1,'unique review import violated');const imported=a.reviews.at(-1),raw=load(r.reportFile);assert(imported.recorded!==null&&typeof imported.recorded==='object'&&!Array.isArray(imported.recorded)&&isDeepStrictEqual(Object.keys(imported.recorded).sort(),['timezone','utc'])&&imported.recorded.timezone==='Asia/Taipei'&&typeof imported.recorded.utc==='string'&&Number.isFinite(Date.parse(imported.recorded.utc))&&new Date(imported.recorded.utc).toISOString()===imported.recorded.utc,'generated recorded object must exactly match frozen now() UTC/timezone shape');const expected={...raw,recorded:imported.recorded};assert(isDeepStrictEqual(imported,expected),'import not complete original report fields');assert(a.behaviorStatus===r.status&&state.behaviorStatus===r.status,'wrong imported original result');
   if(Object.hasOwn(oa,'reviews'))a.reviews=structuredClone(oa.reviews);else delete a.reviews;
   if(Object.hasOwn(oa,'behaviorStatus'))a.behaviorStatus=oa.behaviorStatus;else delete a.behaviorStatus;
   if(Object.hasOwn(origState,'behaviorStatus'))state.behaviorStatus=origState.behaviorStatus;else delete state.behaviorStatus;
   originalFieldsRecovered++;
  }
  assert(isDeepStrictEqual(inverse,original),'unallowed batch field mutation '+br.file);
  if(assigned.length){modifications.push({batchFile:br.file,uniqueOriginalImports:assigned.length,originalSha256:br.originalSha256,newSha256:sha(actualBytes),wholeOriginalJsonInverseExact:true});}else assert(actualBytes.equals(originalBytes),'ungraded/zero batch bytes changed '+br.file);
 }
 function filesIn(d){return fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>{const f=path.join(d,e.name);assert(!e.isSymbolicLink(),'unexpected new symlink');return e.isDirectory()?filesIn(f):e.isFile()?[path.resolve(f)]:[];});}
 const originalPaths=new Set(pre.inventory.map(r=>path.resolve(r.file))),newAllowed=new Set(pre.batches.slice(0,summarizedCount).map(b=>path.resolve(b.summaryFile)));
 for(const b of pre.batches)for(const f of filesIn(path.dirname(b.file)))assert(originalPaths.has(f)||newAllowed.has(f),'unexpected new CLI batch file '+f);
 for(const [i,br]of pre.batches.entries()){const present=fs.existsSync(br.summaryFile);assert(present===(i<summarizedCount),'summary stage boundary differs '+br.runId);if(present){const s=load(br.summaryFile),b=load(br.file);assert(isDeepStrictEqual(s.source,b.source)&&s.packageVersion==='0.1.20'&&s.client==='codex-cli 0.147.0','summary source changed');assert(s.effectStatus==='NOT_MEASURED'&&s.clientUiStatus==='NOT_RUN','CLI summary scope drift');assert(isDeepStrictEqual(s.selectedIds,b.selectedIds),'summary subset changed');assert(s.variants.length===Object.keys(b.cases).length,'summary case count drift');for(const v of s.variants){const st=b.cases[v.variant];const expected={variant:v.variant,plannedTurns:st.plannedTurns,attempts:st.attempts.map(a=>({attemptId:a.attemptId,threadId:a.threadId,turns:a.turns.length,status:a.behaviorStatus})),status:st.behaviorStatus,execution:st.executionStatus};assert(isDeepStrictEqual(v,expected),'summary raw/semantic status changed');}}
 }
 assert(originalFieldsRecovered===gradedCount,'unique imported final count differs');
 return {status:'EXACT_WITH_ONLY_DECLARED_TECHNICAL_IMPORT_FIELDS',sourceCanonical:pre.sourceCanonical,sourceTree:pre.sourceTree,version:pre.version,uniqueOriginalFinalsImported:gradedCount,newSummaries:summarizedCount,immutableFilesUnchanged:unchangedFiles,originalBatchMetadataInverseExact:pre.batches.length,zeroBatchBytesExact:pre.batches.filter(b=>b.actualAttemptCount===0).length,modifications,originalObservedFalseAndLegacyNaUnchanged:true,projection:false,semanticRejudge:false,modelCalls:0,uiEvidenceExcluded:true};
}

