  "findings": [
    {
      "id": "deadline-is-not-independent-of-timer-callback-order",
      "severity": "BLOCKER",
      "file": "C:\\Users\\Admin\\.codex\\worktrees\\html-guide-acceptance\\reviewer\\corrections\\0-1-20\\technical-lifecycle-draft\\capture-lifecycle-draft.mjs",
      "line": 19,
      "excerpt": "  child.on('exit',(code,signal)=>{exit={code,signal,utc:new Date().toISOString(),elapsedMs:elapsedMs()};if(clearExecutionTimerOnExit)clearTimeout(timer);});",
      "supportingLine": 12,
      "rationale": "The proposed recovery contract requires an actual in-deadline process exit. The callback clears the execution timer unconditionally and does not compare observed exit time against its registered deadline. timedOut becomes true only when the timer callback executes. If the event loop delivers an exit callback after the deadline but before the overdue timer callback, exit0 is returned with timedOut=false. Observed exit-before-close is correctly separated, but a late actual exit is not independently rejected as promised. The four existing probe assertions cover early exit/delayed drain and an active timer firing, not late exit with overdue callback not fired.",
      "requiredCorrection": "Create a separate new candidate identity, record timer registration and monotonic deadline, and determine exitInDeadline from actual observed exit time independently of callback delivery. Late exit must remain invalid even if the execution callback had not fired. Do not kill an already exited child merely to encode late classification; record timer firing/kill attempts separately. Keep all old candidates/probe failures/original INVALIDs/38 controls unchanged."
    }
  ],
  "acceptedObservations": [
    {
      "id": "full-drain-after-actual-exit",
      "rationale": "Early actual exit can clear the execution timer while stdout/stderr remain collected through actual close. Output completeness is not inferred from an SDK completion event; no synthetic exit0 is inserted."
    },
    {
      "id": "active-timeout-not-replaced-by-model-completion",
      "rationale": "The active fixture prints an SDK-like message but remains active past deadline; actual timer/kill return and SIGTERM exit/close are separately recorded and remain timedOut."
    },
    {
      "id": "old-invalid-retained",
      "rationale": "Original two live calls remain FAILED_OR_INVALID, with no actual old exit/close/deadline timestamps or kill return reconstructed. Post-task recorder delay and initial shell snapshot warnings do not prove a specific shutdown or pipe cause."
    }
  ],
  "limitations": [
    {
      "id": "no-independent-drain-deadline",
      "rationale": "After exit, the candidate still waits for actual close without an independent drain bound. This preserves full output but does not guarantee a finite close wait; do not promise a close-time limit from the240s execution budget."
    }
  ],
