  "checks": [
    {
      "id": "registered-monotonic-deadline-independent-of-timer-scheduling",
      "result": "PASS",
      "rationale": "Deadline is based on performance.now at timer registration. The exit callback compares its observed monotonic timestamp against that deadline before clearing the timer; equality and lateness set both timedOut and lateExitInvalid. This closes the original V1 callback-order gap without increasing the240000ms budget.",
